 "content": "def transform(grid):
    """Compress each aligned 3x3 patch to its non-background marker color."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = []
    for br in range(0, h, 3):
        row = []
        for bc in range(0, w, 3):
            colors = {
                grid[r][c]
                for r in range(br, min(br + 3, h))
                for c in range(bc, min(bc + 3, w))
                if grid[r][c] not in (0, 5)
            }
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
